//! Kotlin vs Rust config parity: every case in tests/parity/cases.json is built by the Rust core and
//! compared with the config Kotlin's XrayConfig / SingBoxConfig produced for the same input
//! (tests/parity/expected, regenerated by YPtun/sharedUI/src/jvmTest/.../ConfigParityExport.kt).

use serde_json::{Map, Value};
use std::path::PathBuf;
use yptun_core::model::ProxyProfile;
use yptun_core::routing::{RoutingProfile, RoutingRules, TrafficSettings};
use yptun_core::share_link;
use yptun_core::singbox::config::{self as singbox, SingBoxOptions};
use yptun_core::xray::config::{self as xray, XrayOptions};

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/parity")
}

struct Opts<'a> {
    o: Map<String, Value>,
    links: &'a Map<String, Value>,
}

impl Opts<'_> {
    fn str(&self, k: &str, d: &str) -> String {
        self.o.get(k).and_then(Value::as_str).unwrap_or(d).to_string()
    }
    fn str_opt(&self, k: &str) -> Option<String> {
        self.o.get(k).and_then(Value::as_str).map(String::from)
    }
    fn int(&self, k: &str) -> Option<i32> {
        self.o.get(k).and_then(Value::as_i64).map(|v| v as i32)
    }
    fn bool(&self, k: &str, d: bool) -> bool {
        self.o.get(k).and_then(Value::as_bool).unwrap_or(d)
    }
    fn list(&self, k: &str) -> Vec<String> {
        self.o.get(k).and_then(Value::as_array).map(|a| a.iter().filter_map(|v| v.as_str().map(String::from)).collect()).unwrap_or_default()
    }
    fn profile(&self, k: &str) -> Option<ProxyProfile> {
        self.o.get(k).map(|v| profile(v, self.links))
    }
    fn traffic(&self) -> TrafficSettings {
        self.o.get("traffic").map(|v| serde_json::from_value(v.clone()).unwrap()).unwrap_or_default()
    }
    fn routing_profile(&self) -> Option<RoutingProfile> {
        match self.str_opt("routingPreset").as_deref() {
            Some("russiaDirect") => Some(RoutingProfile::russia_direct()),
            Some("chinaDirect") => Some(RoutingProfile::china_direct()),
            _ => self.o.get("routingProfile").map(|v| serde_json::from_value(v.clone()).unwrap()),
        }
    }
}

fn profile(v: &Value, links: &Map<String, Value>) -> ProxyProfile {
    match v {
        Value::String(r) => {
            let link = links.get(r).and_then(Value::as_str).unwrap_or(r);
            share_link::parse(link).unwrap_or_else(|| panic!("unparsable link {r}"))
        }
        other => serde_json::from_value(other.clone()).unwrap(),
    }
}

fn build_xray(p: &ProxyProfile, o: &Opts) -> Result<String, String> {
    let opts = XrayOptions {
        listen_port: o.int("listenPort").unwrap_or(10808),
        listen_host: o.str("listenHost", "127.0.0.1"),
        socks_username: o.str("socksUsername", ""),
        socks_password: o.str("socksPassword", ""),
        olcrtc_chain_port: o.int("olcrtcChainPort"),
        olcrtc_chain_user: o.str("olcrtcChainUser", ""),
        olcrtc_chain_pass: o.str("olcrtcChainPass", ""),
        log_level: o.str("logLevel", "debug"),
        traffic: o.traffic(),
        wireguard_base: o.profile("wireguardBase"),
        routing_profile: o.routing_profile(),
        block_quic: o.bool("blockQuic", true),
        force_family_resolve: o.bool("forceFamilyResolve", true),
        chain_via_dialer_proxy: o.bool("chainViaDialerProxy", false),
        direct_via_base: o.bool("directViaBase", false),
        bypass_lan: o.bool("bypassLan", true),
        second_profile: o.profile("secondProfile"),
        keep_flow_on_chain: o.bool("keepFlowOnChain", false),
        handshake_timeout_sec: o.int("handshakeTimeoutSec"),
        ..Default::default()
    };
    Ok(xray::build(p, &opts))
}

fn build_singbox(p: &ProxyProfile, o: &Opts) -> Result<String, String> {
    let routing = match o.o.get("routing") {
        Some(v) => serde_json::from_value(v.clone()).unwrap(),
        None => RoutingRules { bypass_lan: o.bool("bypassLan", true), ..Default::default() },
    };
    let opts = SingBoxOptions {
        listen_port: o.int("listenPort").unwrap_or(10808),
        listen_host: o.str("listenHost", "127.0.0.1"),
        socks_username: o.str("socksUsername", ""),
        socks_password: o.str("socksPassword", ""),
        olcrtc_chain_port: o.int("olcrtcChainPort"),
        olcrtc_chain_user: o.str("olcrtcChainUser", ""),
        olcrtc_chain_pass: o.str("olcrtcChainPass", ""),
        log_level: o.str("logLevel", "debug"),
        auto_detect_interface: o.bool("autoDetectInterface", false),
        routing,
        traffic: o.traffic(),
        wireguard_base: o.profile("wireguardBase"),
        dns_strategy_override: o.str_opt("dnsStrategyOverride"),
        routing_profile: o.routing_profile(),
        singbox_geosite_base: o.str("singboxGeositeBase", ""),
        singbox_geoip_base: o.str("singboxGeoipBase", ""),
        block_quic: o.bool("blockQuic", true),
        force_family_resolve: o.bool("forceFamilyResolve", true),
        allow_local_resolve: o.bool("allowLocalResolve", true),
        direct_via_base: o.bool("directViaBase", false),
        sniff_override_destination: o.bool("sniffOverrideDestination", false),
        second_profile: o.profile("secondProfile"),
        tun_mode: o.bool("tunMode", false),
        split_tunnel_mode: o.str("splitTunnelMode", singbox::SPLIT_TUNNEL_ALL),
        split_tunnel_processes: o.list("splitTunnelProcesses"),
        tun_exclude_addresses: o.list("tunExcludeAddresses"),
        hijack_dns: o.bool("hijackDns", false),
        log_file_path: o.str_opt("logFilePath"),
        remote_dns_over_https: o.bool("remoteDnsOverHttps", false),
        force_fake_dns: o.bool("forceFakeDns", false),
        mixed_inbound: o.bool("mixedInbound", false),
        match_apps_by_process: o.bool("matchAppsByProcess", false),
        tproxy_port: o.int("tproxyPort"),
        prefer_tcp_remote_dns: o.bool("preferTcpRemoteDns", false),
        cache_file_path: o.str_opt("cacheFilePath"),
        ..Default::default()
    };
    singbox::build(p, &opts).map_err(|e| format!("{e:?}"))
}

/// JSON paths where the two values differ (object key order is ignored).
fn diff(path: &str, a: &Value, b: &Value, out: &mut Vec<String>) {
    match (a, b) {
        (Value::Object(x), Value::Object(y)) => {
            for (k, va) in x {
                match y.get(k) {
                    Some(vb) => diff(&format!("{path}.{k}"), va, vb, out),
                    None => out.push(format!("{path}.{k}: only in Kotlin = {va}")),
                }
            }
            for (k, vb) in y {
                if !x.contains_key(k) {
                    out.push(format!("{path}.{k}: only in Rust = {vb}"));
                }
            }
        }
        (Value::Array(x), Value::Array(y)) if x.len() == y.len() => {
            for (i, (va, vb)) in x.iter().zip(y).enumerate() {
                diff(&format!("{path}[{i}]"), va, vb, out);
            }
        }
        _ if a != b => out.push(format!("{path}: Kotlin = {a} | Rust = {b}")),
        _ => {}
    }
}

#[test]
fn configs_match_kotlin() {
    let root: Value = serde_json::from_str(&std::fs::read_to_string(dir().join("cases.json")).unwrap()).unwrap();
    let links = root["links"].as_object().unwrap();
    let mut failures = Vec::new();
    let mut checked = 0;
    for case in root["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let p = profile(&case["profile"], links);
        let only = case.get("only").and_then(Value::as_str);
        for target in ["xray", "singbox"] {
            if only.is_some_and(|o| o != target) {
                continue;
            }
            let mut o = case.get("opts").and_then(Value::as_object).cloned().unwrap_or_default();
            if let Some(extra) = case.get(target).and_then(Value::as_object) {
                o.extend(extra.clone());
            }
            let opts = Opts { o, links };
            let file = dir().join(format!("expected/{name}.{target}.json"));
            let expected: Value = serde_json::from_str(&std::fs::read_to_string(&file).unwrap_or_else(|_| panic!("missing {}", file.display()))).unwrap();
            let actual = if target == "xray" { build_xray(&p, &opts) } else { build_singbox(&p, &opts) };
            checked += 1;
            let kotlin_error = expected.as_object().filter(|m| m.len() == 1).and_then(|m| m.get("error"));
            match (kotlin_error, actual) {
                (Some(_), Err(_)) => {}
                (Some(e), Ok(_)) => failures.push(format!("{name}.{target}: Kotlin failed ({e}), Rust built a config")),
                (None, Err(e)) => failures.push(format!("{name}.{target}: Rust failed ({e}), Kotlin built a config")),
                (None, Ok(text)) => {
                    let actual: Value = serde_json::from_str(&text).unwrap();
                    let mut d = Vec::new();
                    diff("$", &expected, &actual, &mut d);
                    if !d.is_empty() {
                        failures.push(format!("{name}.{target}:\n    {}", d.join("\n    ")));
                    }
                }
            }
        }
    }
    assert!(checked > 0);
    assert!(failures.is_empty(), "{} of {checked} configs differ from Kotlin:\n{}", failures.len(), failures.join("\n"));
}
